/**
 * Recursos gráficos de marca del PDF de dieta.
 *
 * Van embebidos como data URI y no como ficheros de `public/` porque el entorno
 * de despliegue es serverless y no hay filesystem en runtime (misma razón que
 * `diet-examples.ts`). Además, el render del PDF debe ser hermético: si una
 * imagen se pidiera por red y la petición fallase, el documento saldría sin logo
 * sin que nadie se entere.
 *
 * Origen: extraídos del PDF de referencia `public/diets_example/` con
 * `pdfimages`, y recortados a fondo transparente (alfa = 1 - min(r,g,b), color
 * des-premultiplicado) para que no dejen un recuadro blanco sobre la hoja.
 */

/** Logo de Vitalitty. 655 x 563 px, relación 1.163:1. */
export const VITALITTY_LOGO_DATA_URI =
  "data:image/png;base64,";

/** Icono de Instagram con su marca denominativa. 146 x 145 px. */
export const INSTAGRAM_ICON_DATA_URI =
  "data:image/png;base64,";

/** Proporciones nativas, para no deformar las imágenes al escalarlas. */
export const BRAND_IMAGE_RATIOS = {
  logo: 655 / 563,
  instagram: 146 / 145,
} as const;
